/**
 * What a Legion Button asks for, written into the Button's key.
 *
 * The UI never runs an action itself: every actionable Button's `key` is `encodeAction(action)` and its `onPress` is a
 * no-op. A press still raises `ui.press` with `e.element` = that key, and the lead's `ui.press` hook
 * (src/wire/actions.tsx) answers it with `decodeAction(e.element)`. That split exists because `onPress` receives no
 * `$` and the validator lets `$` reach only functions declared in the hook's own file.
 *
 * Key grammar (one per action, at most 64 characters, the ButtonProps.key limit the lead's hook relies on):
 *
 *   view:<chat|order>      agent:<agentId>      task:<taskId>      new:<agentId>
 *   continue:<taskId>      stop:<taskId>        poke:<agentId>
 *   allow:<cardId>         deny:<cardId>        dismiss:<bandItemId>
 *   keys:open | keys:close (the key-help view)     steps:<taskId> (open a task's folded steps) | steps:close
 *
 * An id that would take a key past 64 characters is written as its index instead, `allow#3`: the position in
 * `cardsInOrder(cards)` (cards) or `bandOrder(band)` (band items), the same orders the UI draws in; `cardAt` and
 * `bandItemAt` resolve it. A Button drawn twice in one site with the same action carries `~2`, `~3`... after its key
 * (`task:t_0123456789ab~2`), which `decodeAction` ignores, so every key in a site is unique.
 */
import type { AgentId, ApprovalCard, BandItem, ViewId } from '../../types/index.d.ts'

export type UiAction =
  | { kind: 'view'; view: ViewId }
  | { kind: 'agent'; agentId: AgentId }
  | { kind: 'task'; taskId: string }
  | { kind: 'new'; agentId: AgentId }
  | { kind: 'continue'; taskId: string }
  | { kind: 'stop'; taskId: string }
  | { kind: 'poke'; agentId: AgentId }
  | { kind: 'card-allow'; cardId: string; index: number }
  | { kind: 'card-deny'; cardId: string; index: number }
  | { kind: 'band-dismiss'; itemId: string; index: number }
  | { kind: 'keys'; open: boolean }
  | { kind: 'steps'; taskId: string | null }

/** What a decoded key names: the action, with an index in place of an id that was too long to write. */
export type DecodedAction =
  | Exclude<UiAction, { kind: 'card-allow' | 'card-deny' | 'band-dismiss' }>
  | { kind: 'card-allow' | 'card-deny'; cardId: string }
  | { kind: 'card-allow' | 'card-deny'; index: number }
  | { kind: 'band-dismiss'; itemId: string }
  | { kind: 'band-dismiss'; index: number }

export const KEY_MAX = 64

const PREFIX = {
  view: 'view', agent: 'agent', task: 'task', new: 'new', continue: 'continue', stop: 'stop', poke: 'poke',
  'card-allow': 'allow', 'card-deny': 'deny', 'band-dismiss': 'dismiss', keys: 'keys', steps: 'steps',
} as const satisfies Record<UiAction['kind'], string>

const KIND_OF: Record<string, UiAction['kind']> = Object.fromEntries(Object.entries(PREFIX).map(([k, p]) => [p, k as UiAction['kind']]))

const idOf = (a: UiAction): string => {
  switch (a.kind) {
    case 'view': return a.view
    case 'agent': case 'new': case 'poke': return a.agentId
    case 'task': case 'continue': case 'stop': return a.taskId
    case 'card-allow': case 'card-deny': return a.cardId
    case 'band-dismiss': return a.itemId
    case 'keys': return a.open ? 'open' : 'close'
    case 'steps': return a.taskId ?? 'close'
  }
}

/** The Button key for an action; an id too long for 64 characters is written as its index (`allow#3`). */
export const encodeAction = (a: UiAction): string => {
  const key = `${PREFIX[a.kind]}:${idOf(a)}`
  if (key.length <= KEY_MAX) return key
  if (a.kind === 'card-allow' || a.kind === 'card-deny' || a.kind === 'band-dismiss') return `${PREFIX[a.kind]}#${a.index}`
  // agent, task and view ids are short by contract (roster ids, `t_` + 12 hex); one that is not is cut, never silently
  // merged with another: the lead's hook finds no such agent or task and says so
  return key.slice(0, KEY_MAX)
}

const VIEWS: ReadonlySet<string> = new Set(['chat', 'rooms', 'library', 'board', 'order'])

/** The action a Button key names, or null for a key that is not one of Legion's (another plugin's, a typo). */
export const decodeAction = (key: string): DecodedAction | null => {
  const bare = key.replace(/~\d+$/, '')
  const m = /^([a-z]+)([:#])(.+)$/.exec(bare)
  if (!m) return null
  const [, prefix, sep, rest] = m as unknown as [string, string, string, string]
  const kind = KIND_OF[prefix]
  if (!kind) return null
  if (sep === '#') {
    if (!/^\d+$/.test(rest)) return null
    const index = Number(rest)
    if (kind === 'card-allow' || kind === 'card-deny') return { kind, index }
    if (kind === 'band-dismiss') return { kind, index }
    return null
  }
  switch (kind) {
    case 'view': return VIEWS.has(rest) ? { kind, view: rest as ViewId } : null
    case 'agent': case 'new': case 'poke': return { kind, agentId: rest }
    case 'task': case 'continue': case 'stop': return { kind, taskId: rest }
    case 'card-allow': case 'card-deny': return { kind, cardId: rest }
    case 'band-dismiss': return { kind, itemId: rest }
    case 'keys': return rest === 'open' || rest === 'close' ? { kind, open: rest === 'open' } : null
    case 'steps': return { kind, taskId: rest === 'close' ? null : rest }
  }
}

/** Cards in the order the UI draws them, oldest first: the first is the one `a` and `d` answer. */
export const cardsInOrder = (cards: readonly ApprovalCard[]): ApprovalCard[] => [...cards].sort((a, b) => a.at - b.at || a.id.localeCompare(b.id))

/** Band items in the order the band draws them: newest first, cards left out (they come from `cards`). */
export const bandOrder = (band: readonly BandItem[]): BandItem[] => band.filter(i => i.kind !== 'card').sort((a, b) => b.at - a.at || a.id.localeCompare(b.id))

/** The card an `allow#n` / `deny#n` key names. */
export const cardAt = (cards: readonly ApprovalCard[], index: number): ApprovalCard | undefined => cardsInOrder(cards)[index]

/** The band item a `dismiss#n` key names. */
export const bandItemAt = (band: readonly BandItem[], index: number): BandItem | undefined => bandOrder(band)[index]

files.src/wire/trace.ts:
/**
 * The development trace: every decision the runtime makes, one JSON line each, so "did Zealot delegate, to whom, what was
 * refused and why" is one command away (`node scripts/mod-trace.mjs`), not an archaeology session.
 *
 * Off by default: `LEGION_MOD_TRACE=1` in the environment, or `/legion trace on` for the session. Off costs one boolean check per
 * call site and writes nothing. On, lines are kept in memory (the last MAX_LINES) and the session's own file is rewritten at most
 * once a second (`$.fs` has no append). The file is the session's alone, under `<data root>/debug/`, never shared.
 *
 * What it holds: ids, agent ids, tool names, counts, reasons, and text cut to TEXT_MAX characters. Nothing secret passes through
 * the runtime, but prompts and answers are the person's words: cut, local, and off unless asked for.
 */
export const MAX_LINES = 4000
export const TEXT_MAX = 160
export const FLUSH_MS = 1000

export type TraceKind =
  | 'boot' | 'cmd' | 'queue' | 'result' | 'adopt' | 'step' | 'tool' | 'deny' | 'toolDone' | 'reply' | 'finish'
  | 'mood' | 'drop' | 'channel' | 'stage' | 'error'

export type TraceLine = { t: number; k: TraceKind; task?: string; agent?: string; run?: string } & Record<string, unknown>

export type Trace = {
  isOn: boolean
  lines: TraceLine[]
  /** True when lines were added since the last flush. */
  isDirty: boolean
}

export const newTrace = (isOn: boolean): Trace => ({ isOn, lines: [], isDirty: false })

/** Cuts a value for the trace: strings to TEXT_MAX with an ellipsis; anything else as it is. */
export function cut(v: unknown, max = TEXT_MAX): unknown {
  if (typeof v !== 'string') return v
  const one = v.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

/** Adds one line when tracing is on. Returns whether it did. */
export function record(trace: Trace, line: TraceLine): boolean {
  if (!trace.isOn) return false
  const clean: TraceLine = { t: line.t, k: line.k }
  for (const [key, value] of Object.entries(line)) if (key !== 't' && key !== 'k' && value !== undefined) clean[key] = cut(value)
  trace.lines.push(clean)
  if (trace.lines.length > MAX_LINES) trace.lines.splice(0, trace.lines.length - MAX_LINES)
  trace.isDirty = true
  return true
}

/** The file text for the current lines. */
export const traceText = (trace: Trace): string => trace.lines.map(l => JSON.stringify(l)).join('\n') + (trace.lines.length ? '\n' : '')

/** The session's trace file, relative to the data root's folder. */
export const traceFile = (sessionId: string): string => `debug/trace-${sessionId.replace(/[^A-Za-z0-9_-]/g, '_')}.jsonl`

files.src/wire/core.ts:
/**
 * The wiring's pure half: the runtime's memory (Ctx) and every decision the hooks make that needs no `$`.
 *
 * src/wire/legion.tsx holds the hooks; anything here is plain logic over plain data, tested in mod/test/node/wire. Keeping
 * the decisions here keeps the hooks file to "read the event, ask core, write the result".
 */
import type { AgentId, AgentView, ApprovalCard, BandItem, ModSettings, MoodState, RunRequest, TaskOrigin, TaskView, ThreadRow, UiState } from '../../types/index.d.ts'
import type { RateLog } from '../engine/bridge.ts'
import { agentTypeName } from '../engine/prompt.ts'
import { AGENT_TYPE_PREFIX } from '../engine/tool-names.ts'
import { ZERO_TOKENS } from '../engine/cost.ts'

/** The runtime's memory for one session. Module variables reset on a hot reload; boot restores this from the stores. */
export type Ctx = {
  isReady: boolean
  sessionId: string
  settings: ModSettings
  agents: AgentView[]
  tasks: Map<string, TaskView>
  /** Thread rows of the tasks this session has touched, by task id. */
  threads: Map<string, ThreadRow[]>
  /** Claude Code agent id of a run → Legion task id. */
  byRun: Map<string, string>
  /** Requests queued for legion-mod-runner, by request id, until it answers. */
  pending: Map<string, RunRequest>
  /** Results already applied (request ids), so a result is applied once. */
  applied: Set<string>
  /** Stop reason of each run's last model request (turn-limit inference). */
  lastStop: Map<string, string | null>
  /** tool_use_id → run id, so tool.check (which carries no agent id) knows the run. */
  toolRun: Map<string, string>
  /** Runs blocked inside a Legion ask (the bridge's deadlock guard). */
  waiting: Set<string>
  rateLog: RateLog
  moods: Record<AgentId, MoodState>
  ui: UiState
  band: BandItem[]
  cards: ApprovalCard[]
  /** Streaming text of a running reply, by task id. */
  live: Map<string, string>
}

export const DEFAULT_UI: UiState = { view: 'chat', agentId: 'zealot', taskId: null, channel: null }

export function newCtx(settings: ModSettings): Ctx {
  return {
    isReady: false, sessionId: '', settings, agents: [], tasks: new Map(), threads: new Map(), byRun: new Map(), pending: new Map(),
    applied: new Set(), lastStop: new Map(), toolRun: new Map(), waiting: new Set(), rateLog: {}, moods: {}, ui: { ...DEFAULT_UI },
    band: [], cards: [], live: new Map(),
  }
}

/** A task's title: the first non-empty line of the message, at most 80 characters, cut on a word where it can be. */
export function titleFrom(text: string): string {
  const first = text.split(/\r?\n/).map(l => l.trim()).find(l => l.length > 0) ?? ''
  if (first.length <= 80) return first || 'Untitled task'
  const cut = first.slice(0, 79)
  const space = cut.lastIndexOf(' ')
  return `${space > 50 ? cut.slice(0, space) : cut}…`
}

export function makeTask(o: { id: string; agentId: AgentId; text: string; sessionId: string; origin: TaskOrigin; now: number; projectId?: string }): TaskView {
  return {
    id: o.id, agentId: o.agentId, title: titleFrom(o.text), status: 'queued', sessionId: o.sessionId, isEscalated: false, isTainted: false,
    turns: 0, runTurns: 0, tokens: { ...ZERO_TOKENS }, costUsd: 0, origin: o.origin, createdAt: o.now, updatedAt: o.now,
    ...(o.projectId ? { projectId: o.projectId } : {}),
  }
}

/** The one-line description Claude Code shows in its own agent list. */
export const runDescription = (agent: AgentView, task: TaskView): string => `${agent.name} · ${task.title}`.slice(0, 120)

export function spawnRequest(o: { id: string; task: TaskView; agent: AgentView; prompt: string; model?: string; now: number }): RunRequest {
  return {
    id: o.id, kind: 'spawn', taskId: o.task.id, agentType: `${AGENT_TYPE_PREFIX}${agentTypeName(o.agent.id)}`, name: `${o.agent.id}-${o.task.id}`, prompt: o.prompt,
    description: runDescription(o.agent, o.task), at: o.now, ...(o.model ? { model: o.model } : {}),
  }
}

export const resumeRequest = (o: { id: string; task: TaskView; text: string; now: number }): RunRequest =>
  ({ id: o.id, kind: 'resume', taskId: o.task.id, runId: o.task.runId, prompt: o.text, at: o.now })

export const stopRequest = (o: { id: string; task: TaskView; now: number }): RunRequest =>
  ({ id: o.id, kind: 'stop', taskId: o.task.id, runId: o.task.runId, at: o.now })

/** The run id a background-task notification names (`<task-id>…</task-id>`), or null. */
export function notificationRunId(text: string): string | null {
  const m = /<task-id>\s*([A-Za-z0-9_-]{4,80})\s*<\/task-id>/.exec(text)
  return m?.[1] ?? null
}

/** The text of an assistant row's content blocks (text blocks only), joined; '' when there is none. */
export function assistantText(content: unknown): string {
  if (typeof content === 'string') return content.trim()
  if (!Array.isArray(content)) return ''
  return content
    .filter((b): b is { type: 'text'; text: string } => !!b && typeof b === 'object' && (b as { type?: unknown }).type === 'text' && typeof (b as { text?: unknown }).text === 'string')
    .map(b => b.text)
    .join('\n')
    .trim()
}

/** An agent by id, name or glyph, among the agents a person may address (hidden ones are not). Case-insensitive. */
export function resolveAgent(ref: string, agents: readonly AgentView[]): AgentView | undefined {
  const r = ref.trim().replace(/^@/, '').toLowerCase()
  if (!r) return undefined
  const shown = agents.filter(a => !a.isHidden)
  return shown.find(a => a.id.toLowerCase() === r) ?? shown.find(a => a.name.toLowerCase() === r) ?? shown.find(a => a.glyph === ref.trim())
}

/** `/to <agent> <text>`: the agent and the message, or what is missing, in plain words. */
export function parseTo(args: string, agents: readonly AgentView[]): { agent: AgentView; text: string } | { error: string } {
  const trimmed = args.trim()
  const space = trimmed.search(/\s/)
  const ref = space === -1 ? trimmed : trimmed.slice(0, space)
  const text = space === -1 ? '' : trimmed.slice(space).trim()
  if (!ref) return { error: 'Usage: /to <agent> <message>. For example: /to zealot ship the replay fix' }
  const agent = resolveAgent(ref, agents)
  if (!agent) return { error: `No agent called "${ref}". The order: ${agents.filter(a => !a.isHidden).map(a => a.id).join(', ')}.` }
  if (!text) return { error: `What should ${agent.name} do? Usage: /to ${agent.id} <message>.` }
  return { agent, text }
}

/** Tasks newest first, as the state publishes them. */
export const taskList = (ctx: Ctx): TaskView[] => [...ctx.tasks.values()].sort((a, b) => b.updatedAt - a.updatedAt || b.createdAt - a.createdAt)

/** The newest task of an agent that this session may act on (its own), or none. */
export function latestTaskOf(ctx: Ctx, agentId: AgentId): TaskView | undefined {
  return taskList(ctx).find(t => t.agentId === agentId && t.sessionId === ctx.sessionId)
}

/** Why a Legion agent's Agent call to a non-Legion type is refused, and how to do it right. */
export function orderOnlyMessage(subagentType: unknown, agents: readonly AgentView[]): string {
  const who = agents.filter(a => !a.isHidden).map(a => a.id).join(', ')
  const used = typeof subagentType === 'string' && subagentType.trim() ? subagentType : 'no subagent_type (Claude Code\'s general-purpose agent)'
  return `Delegate inside the Order: set subagent_type to legion-mod:<agent id>; you used ${used}. The Order: ${who}. mcp__legion-mod__agents says who is busy.`
}

/** The engine's envelope on a tool call (claude-code.d.ts ToolCallReserved, AgentLoop): not part of what the tool was asked. */
const ENVELOPE = new Set(['tool', 'tool_use_id', 'consent', 'agentId'])

/** A tool call's own input, without the engine's envelope fields. */
export function toolInput(e: Record<string, unknown>): Record<string, unknown> {
  return Object.fromEntries(Object.entries(e).filter(([k]) => !ENVELOPE.has(k)))
}

/**
 * The one line a thread shows for a tool call. A delegation inside the Order reads as the person would say it, "Ask Scout:
 * check the engines field"; everything else uses the desktop's summary rule (approvals.ts summarizeToolInput).
 */
export function toolLine(tool: string, input: Record<string, unknown>, agents: readonly AgentView[], summarize: (tool: string, input: Record<string, unknown>) => string): string {
  if (tool === 'Agent' && typeof input.subagent_type === 'string' && input.subagent_type.startsWith('legion-mod:')) {
    const id = input.subagent_type.slice('legion-mod:'.length)
    const name = agents.find(a => a.id === id)?.name ?? id
    const what = typeof input.description === 'string' && input.description.trim()
      ? input.description.trim()
      : titleFrom(typeof input.prompt === 'string' ? input.prompt : '')
    return `${input.run_in_background === false ? 'Ask' : 'Tell'} ${name}: ${what}`
  }
  return summarize(tool, input)
}

/** Band rows are capped: at most 20 kept, newest last; a newer row for the same task replaces the older one. */
export function pushBand(band: readonly BandItem[], item: BandItem): BandItem[] {
  const rest = band.filter(b => !(item.taskId && b.taskId === item.taskId && b.kind !== 'card') && b.id !== item.id)
  return [...rest, item].slice(-20)
}

/**
 * The one line the main conversation shows when a Legion run stops (its task notification is dropped, and Claude Code
 * shows the drop's reason): `✠ Zealot · Report the version… · its result is in the Legion pane`. No state word: the
 * notification can come for a task that is done, paused or failed, and the pane says which.
 */
export const finishedLine = (agent: Pick<AgentView, 'glyph' | 'name'>, task: Pick<TaskView, 'title'>): string => {
  const title = task.title.length > 60 ? `${task.title.slice(0, 59)}…` : task.title
  return `${agent.glyph} ${agent.name} · ${title} · its result is in the Legion pane`
}

